class Solution:
    def isPalindrome(self, s: str) -> bool:
        # 对撞双指针：l 从左向右找「合法字符」，r 从右向左找，逐对比较
        l, r = 0, len(s) - 1
        while l < r:
            # 易错点：两侧都要用 while 跳过无效字符，而不是 if——可能连续出现标点空格
            while l < r and not s[l].isalnum():
                l += 1
            while l < r and not s[r].isalnum():
                r -= 1
            if s[l].lower() != s[r].lower():   # 统一小写后再比较，数字不受影响
                return False
            l += 1
            r -= 1
        return True    # 空串或全符号串会在循环中相遇，按定义视为回文

