class Solution {
public:
    bool isPalindrome(string s) {
        // 字符判定：字母或数字（等价 Python 的 isalnum，手动实现不依赖 cctype）
        auto isAlnum = [](char c) {
            return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
        };
        // 转小写：大写字母减偏移，其余字符不变
        auto low = [](char c) {
            return (c >= 'A' && c <= 'Z') ? (char)(c - 'A' + 'a') : c;
        };
        // 对撞双指针：l 从左向右找合法字符，r 从右向左找，逐对比较
        int l = 0, r = (int)s.size() - 1;
        while (l < r) {
            // 易错点：两侧都要用 while 跳过非字母数字字符，而不是 if——可能连续出现标点空格
            while (l < r && !isAlnum(s[l])) ++l;
            while (l < r && !isAlnum(s[r])) --r;
            // 统一转小写后比较；数字字符不受影响
            if (low(s[l]) != low(s[r])) return false;
            ++l; --r;   // 相等则同步内移
        }
        return true;    // 空串或全符号串会在循环中相遇，按定义视为回文
    }
};

