// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：一行字符串 s（可含空格、标点、大小写字母与数字）
// 输出格式：true 或 false
#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    getline(cin, s);   // 整行读取，保留内容中的空格
    if (!s.empty() && s.back() == '\r') s.pop_back();   // 兼容 Windows 换行

    // 字符判定：字母或数字
    auto isAlnum = [](char c) {
        return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
    };
    // 转小写：大写字母减偏移，其余字符不变
    auto low = [](char c) {
        return (c >= 'A' && c <= 'Z') ? (char)(c - 'A' + 'a') : c;
    };

    int l = 0, r = (int)s.size() - 1;
    bool ok = true;
    while (l < r) {
        // 两侧各自用 while 跳过非字母数字字符，内层保留 l < r 防越界
        while (l < r && !isAlnum(s[l])) ++l;
        while (l < r && !isAlnum(s[r])) --r;
        // 统一转小写后比较，不等即非回文
        if (low(s[l]) != low(s[r])) { ok = false; break; }
        ++l; --r;   // 相等则同步内移
    }
    cout << (ok ? "true" : "false") << endl;
    return 0;
}

