def twoSum_binary(numbers, target):
    n = len(numbers)
    for i in range(n):
        need = target - numbers[i]
        # 在 i 右侧 [i+1, n-1] 二分查找 need，避免配到自己
        lo, hi = i + 1, n - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if numbers[mid] == need:
                return [i + 1, mid + 1]   # 下标从 1 开始
            if numbers[mid] < need:
                lo = mid + 1
            else:
                hi = mid - 1
    return []

def twoSum_tp(numbers, target):
    # 有序数组找两数之和：对撞双指针，每一步安全淘汰一个不可能的数
    l, r = 0, len(numbers) - 1
    while l < r:
        s = numbers[l] + numbers[r]
        if s == target:
            return [l + 1, r + 1]   # 易错点：题目下标从 1 开始，要 +1
        if s < target:
            l += 1      # 和偏小：固定 r 时只有更大的 l 可能达标
        else:
            r -= 1      # 和偏大：固定 l 时只有更小的 r 可能达标
    return []           # 题目保证有解，此行仅为语法完整

