// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：
//   第一行：n（数组长度）
//   第二行：n 个整数（非递减有序）
//   第三行：target
// 输出格式：一行两个下标（从 1 开始），空格分隔
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 关闭同步，读入更快
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> numbers(n);
    for (auto& x : numbers) cin >> x;
    int target;
    cin >> target;

    int l = 0, r = n - 1;   // 对撞双指针：每一步安全淘汰一个不可能的数
    while (l < r) {
        int s = numbers[l] + numbers[r];
        if (s == target) {   // 命中：输出下标（从 1 开始）
            cout << l + 1 << " " << r + 1 << endl;
            return 0;
        }
        if (s < target)
            ++l;   // 和偏小，只有更大的 l 可能达标
        else
            --r;   // 和偏大，只有更小的 r 可能达标
    }
    return 0;
}

